// Webhook에서 받은 문의 데이터 추출 및 포맷팅
console.log('[Extract Inquiry Data] 수신된 데이터:', JSON.stringify(items[0].json, null, 2));

const webhookData = items[0].json.body || items[0].json;
const inquiry = webhookData.inquiry || webhookData;

console.log(`[Inquiry Monitor] 새 문의 감지: ${inquiry._id || inquiry.inquiryId || 'unknown'}`);

// 문의 정보 추출
const inquiryData = {
  inquiryId: inquiry._id ? inquiry._id.toString() : inquiry.inquiryId || 'temp-' + Date.now(),
  userId: inquiry.userId ? inquiry.userId.toString() : null,
  userEmail: inquiry.userEmail || 'test@example.com',
  userName: inquiry.userName || '테스트 사용자',
  type: inquiry.type || 'general',
  subject: inquiry.subject || '테스트 문의',
  content: inquiry.content || '테스트 내용',
  status: inquiry.status || 'pending',
  createdAt: inquiry.createdAt || new Date().toISOString(),

  // AI 답변 생성을 위한 컨텍스트
  context: {
    inquiryType: inquiry.type || 'general',
    subject: inquiry.subject || '테스트 문의',
    content: inquiry.content || '테스트 내용',
    userInfo: {
      email: inquiry.userEmail || 'test@example.com',
      name: inquiry.userName || '테스트 사용자'
    }
  },

  // 검색용 텍스트 (임베딩에 사용)
  searchText: `${inquiry.type || 'general'} ${inquiry.subject || '테스트 문의'} ${inquiry.content || '테스트 내용'}`.trim()
};

console.log(`[Inquiry Monitor] 처리할 문의: ${inquiryData.subject}`);
console.log('[Extract Inquiry Data] 추출된 데이터:', JSON.stringify(inquiryData, null, 2));

return [{
  json: inquiryData
}];

// 임베딩 결과 처리
// 이전 노드들의 데이터를 모두 포함
const previousData = items[0].json;
const embeddingResponse = items[0].json.data;

// 원본 inquiry 데이터 복원
const inquiryData = {
  inquiryId: previousData.inquiryId,
  userId: previousData.userId,
  userEmail: previousData.userEmail,
  userName: previousData.userName,
  type: previousData.type,
  subject: previousData.subject,
  content: previousData.content,
  status: previousData.status,
  createdAt: previousData.createdAt,
  context: previousData.context,
  searchText: previousData.searchText
};

// 임베딩 추가
if (embeddingResponse && embeddingResponse[0]) {
  inquiryData.embedding = embeddingResponse[0].embedding;
  console.log(`[Inquiry Monitor] 임베딩 생성 완료: ${inquiryData.inquiryId}`);
} else {
  console.warn(`[Inquiry Monitor] 임베딩 생성 실패: ${inquiryData.inquiryId}`);
  inquiryData.embedding = null;
}

return [{ json: inquiryData }];

// 관련 컨텍스트와 문의 데이터 결합
const inquiryData = items[0].json;
const contextResponse = items[0].json;

// 컨텍스트 정보 추출
const relatedContext = contextResponse.context || [];
const contextText = relatedContext.map(ctx => 
  `[${ctx.type}] ${ctx.title || ctx.name}: ${ctx.content}`
).join('\n\n');

// AI 답변 생성을 위한 최종 데이터 구성
const aiRequestData = {
  inquiryId: inquiryData.inquiryId,
  userQuery: inquiryData.content,
  inquiryType: inquiryData.type,
  subject: inquiryData.subject,
  context: contextText,
  userInfo: inquiryData.context.userInfo,

  // AI 프롬프트 구성
  systemPrompt: `당신은 Youniqle 쇼핑몰의 친절한 고객 상담 AI입니다.

고객 정보:
- 이름: ${inquiryData.context.userInfo.name}
- 이메일: ${inquiryData.context.userInfo.email}
- 문의 유형: ${inquiryData.type}

답변 원칙:
1. 반드시 한국어로만 답변하세요
2. 친절하고 전문적인 톤을 유지하세요
3. 구체적이고 도움이 되는 정보를 제공하세요
4. 추가 문의가 필요하면 고객센터 연락처를 안내하세요

참고 정보를 바탕으로 고객의 문의에 정확하고 도움이 되는 답변을 작성해주세요.`,

  userPrompt: `문의 제목: ${inquiryData.subject}\n\n문의 내용: ${inquiryData.content}\n\n참고 정보:\n${contextText}\n\n위 정보를 바탕으로 친절하고 정확한 답변을 작성해주세요.`
};

console.log(`[Inquiry Monitor] AI 답변 요청 준비 완료: ${inquiryData.inquiryId}`);

return [{ json: aiRequestData }];

// Prepare AI Request 노드의 데이터를 받아서 Gemini API에 보낼 JSON 구성
const aiRequestData = items[0].json;

// Gemini API에 보낼 요청 본문 구성
const geminiRequest = {
  contents: [
    {
      role: "user",
      parts: [
        {
          text: `${aiRequestData.systemPrompt}\n\n${aiRequestData.userPrompt}`
        }
      ]
    }
  ],
  generationConfig: {
    temperature: 0.7,
    topK: 40,
    topP: 0.9,
    maxOutputTokens: 1000,
    responseMimeType: "text/plain"
  }
};

console.log('[Build Gemini Request] JSON 구성 완료');
console.log('Model: gemini-2.5-flash');

// JSON을 문자열로 변환하여 반환
return [{
  json: {
    ...aiRequestData,
    geminiRequestJson: JSON.stringify(geminiRequest)
  }
}];

// AI 응답 처리 및 데이터베이스 저장 준비
// 이전 노드들의 데이터를 모두 포함
const previousData = items[0].json;
const geminiResponse = items[0].json;

// Gemini API 응답 구조 확인
console.log('[Process AI Response] Gemini API 응답 수신');
console.log('Response keys:', Object.keys(geminiResponse));

// Gemini API 응답에서 AI 답변 추출
let aiAnswer = null;
if (geminiResponse.candidates && geminiResponse.candidates[0] && geminiResponse.candidates[0].content) {
  const content = geminiResponse.candidates[0].content;
  if (content.parts && content.parts[0]) {
    aiAnswer = content.parts[0].text;
    console.log(`[Process AI Response] AI 답변 추출 성공 (${aiAnswer.length}자)`);
  }
}

if (!aiAnswer) {
  console.error('[Process AI Response] AI 답변 추출 실패');
  console.error('Response:', JSON.stringify(geminiResponse, null, 2));
}

if (aiAnswer) {
  // 답변 데이터 구성
  const answerData = {
    inquiryId: previousData.inquiryId,
    answer: aiAnswer,
    status: 'ai_draft', // 관리자 검토 대기
    generatedBy: 'ai',
    generatedAt: new Date().toISOString(),
    context: previousData.context,
    userInfo: previousData.userInfo,

    // 관리자 검토용 메타데이터
    metadata: {
      aiModel: 'gemini-2.5-flash',
      responseLength: aiAnswer.length,
      confidence: 'high',
      needsReview: true,
      geminiResponse: {
        finishReason: geminiResponse.candidates[0].finishReason,
        usageMetadata: geminiResponse.usageMetadata
      }
    }
  };

  console.log(`[Process AI Response] 답변 데이터 구성 완료: ${answerData.inquiryId}`);
  return [{ json: answerData }];
} else {
  console.error(`[Process AI Response] AI 답변 생성 실패: ${previousData.inquiryId}`);

  // 실패 시 기본 응답
  const fallbackData = {
    inquiryId: previousData.inquiryId,
    answer: '죄송합니다. 현재 시스템에 일시적인 문제가 발생했습니다. 고객센터로 직접 문의해 주시기 바랍니다.',
    status: 'manual_review',
    generatedBy: 'system',
    generatedAt: new Date().toISOString(),
    error: 'AI response generation failed',
    rawResponse: geminiResponse
  };

  return [{ json: fallbackData }];
}

// 성공 로그 및 알림
const answerData = items[0].json;

console.log(`✅ [Inquiry Monitor] 완료: ${answerData.inquiryId}`);
console.log(`   - 답변 상태: ${answerData.status}`);
console.log(`   - 생성자: ${answerData.generatedBy}`);
console.log(`   - 답변 길이: ${answerData.answer.length}자`);
console.log(`   - 시각: ${answerData.generatedAt}`);

// 관리자에게 알림 (선택사항)
if (answerData.status === 'ai_draft') {
  console.log(`📧 [Inquiry Monitor] 관리자 검토 필요: ${answerData.inquiryId}`);
}

return [{ json: answerData }];

// 에러 로그
const error = $json.error || 'Unknown error';
console.error(`❌ [Inquiry Monitor] 에러:`, error);
console.error(`   - 데이터:`, JSON.stringify($json, null, 2));

// 에러를 무시하고 계속 진행
return [];
